<?php declare(strict_types=1);$canWrite=in_array($p['role'],['owner','editor','quality'],true);$canApprove=in_array($p['role'],['owner','quality'],true);$labels=['name'=>'Denumire','ingredients'=>'Ingrediente','allergens'=>'Alergeni','net_quantity'=>'Cantitate','storage'=>'Păstrare','nutrition'=>'Nutriție']; ?>
<div class="container page-space"><a class="back-link" href="<?=$item?'/manage/items/'.e($item['id']):'/manage'?>">← <?=$item?'Articolul comercial':'Spațiul producătorului'?></a><div class="eyebrow">SURSE EXTERNE</div><h1 class="page-title"><?=e($item?$item['name']:'Informații și diferențe')?></h1><p><a href="/surse/open-food-facts">Proveniență și licențe</a><?php if(in_array($p['role'],['owner','quality'],true)&&\App\Core\Migrations::externalSharing()):?> · <a href="/manage/sources/openfoodfacts/sharing">Distribuire voluntară către Open Food Facts</a><?php endif?></p>
<?php if($item):?><section class="panel"><h2>Fișa Open Food Facts</h2><?php if(!$item['gtin14']):?><p>Articolul nu are încă un GTIN. Completează identificatorul pentru a putea căuta o fișă externă.</p><?php elseif(!$record):?><p>Nu avem încă o fișă externă pentru acest GTIN. Pagina produsului și loturile funcționează independent.</p><?php endif?><?php if($item['gtin14']&&$canWrite):?><form method="post"><?=csrf()?><input type="hidden" name="action" value="lookup"><button class="btn btn-outline-primary">Caută după GTIN</button></form><?php endif?><?php if($report&&isset($report['state'])):?><p class="mt-3" role="status"><?=e(match($report['result_code']??'queued'){'found'=>'Fișa a fost găsită.','not_found'=>'Produsul nu a fost găsit în sursa externă.',default=>'Căutarea este programată. Poți continua administrarea produsului.'})?></p><?php endif?></section>
<?php if($record):?><div class="admin-columns"><section class="panel"><?php if($record['source_environment']==='staging'):?><p class="small">Mediul de test Open Food Facts</p><?php endif?><h2><?=e($record['name']??'Fișă externă')?></h2><p><?=e($record['brand']??'')?> <?=e($record['net_quantity']??'')?></p><p class="preserve-lines"><?=e($record['ingredients']??'Lista ingredientelor nu este disponibilă.')?></p><p class="small muted">Open Food Facts · <?=e(ro_time(substr($record['fetched_at'],0,19)))?></p><a href="<?=e($record['source_url'])?>" rel="noopener">Vezi fișa originală ↗</a><p class="mt-3 small">Datele externe nu sunt o declarație verificată de OpenAliment. Verifică eticheta și formula aplicabilă.</p></section>
<section class="panel"><h2>Completează o ciornă</h2><?php if($canWrite):?><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="revision_id" value="<?=e($record['id'])?>"><input type="hidden" name="expected_label_id" value="<?=e($item['current_info_id']??'')?>"><fieldset><legend class="h6">Câmpurile de preluat</legend><?php foreach($labels as$key=>$name):?><label class="check-label"><input type="checkbox" name="fields[]" value="<?=e($key)?>" <?=in_array($key,['name','ingredients','net_quantity'],true)?'checked':''?>> <?=e($name)?></label><?php endforeach?></fieldset><label>Versiunea noii ciorne<input name="version_key" class="form-control" maxlength="60" value="OFF-<?=e(gmdate('Ymd-Hi'))?>"></label><?php if(!$item['current_info_id']):?><label>Categorie<input name="completion[category]" class="form-control" maxlength="80"></label><label>Operatorul responsabil<input name="completion[operator]" class="form-control" maxlength="500"></label><label>Declarația alergenilor<input name="completion[allergens]" class="form-control" maxlength="1500"></label><?php endif?><div class="button-row"><button class="btn btn-outline-primary" name="action" value="preview">Compară înainte de import</button><button class="btn btn-primary" name="action" value="draft">Creează ciorna</button></div></form><?php else:?><p>Poți consulta fișa. Crearea unei ciorne necesită drept de modificare.</p><?php endif?></section></div><?php endif?>
<?php if(isset($report['changes'])):?><section class="panel"><h2>Comparația câmpurilor selectate</h2><?php foreach($report['changes']as$key=>$change):?><div class="mb-4"><h3><?=e($labels[$key]??$key)?></h3><dl class="preview-data"><dt>Informația curentă</dt><dd class="preserve-lines"><?=e($change['current']??'Necompletat')?></dd><dt>Open Food Facts</dt><dd class="preserve-lines"><?=e($change['external'])?></dd></dl></div><?php endforeach?></section><?php endif?>
<?php else:?><section class="panel"><h2>Articole urmărite</h2><?php if(!$bindings):?><p>Dintr-un articol comercial poți consulta și compara fișa Open Food Facts.</p><?php endif?><?php foreach($bindings as$binding):?><a class="list-row" href="/manage/items/<?=e($binding['trade_item_id'])?>/sources"><span><strong><?=e($binding['name'])?></strong><small><?=e($binding['gtin14'])?></small></span><?=icon('arrow')?></a><?php endforeach?></section><?php endif?>
<section class="panel"><h2>Diferențe de verificat</h2><?php if(!$conflicts):?><p>Nu există diferențe înregistrate pentru articolele urmărite.</p><?php endif?><?php foreach($conflicts as$conflict):if($item&&$conflict['trade_item_id']!==$item['id'])continue;?><details class="mb-3"><summary><?=e($conflict['severity']==='important'?'Ingrediente, alergeni sau nutriție':'Informații despre produs')?> · <?=e(['open'=>'De verificat','accepted'=>'Ciornă creată','rejected'=>'Respins','different_market'=>'Altă piață'][$conflict['state']]??$conflict['state'])?></summary><?php foreach($conflict['differences']as$key=>$change):?><h3 class="h6 mt-3"><?=e($labels[$key]??$key)?></h3><p class="preserve-lines"><strong>Curent:</strong> <?=e($change['local']??'Necompletat')?></p><p class="preserve-lines"><strong>Sursa externă:</strong> <?=e($change['external']??'Necompletat')?></p><?php endforeach?><?php if($canApprove&&$conflict['state']==='open'):?><form method="post" class="form-stack"><?=csrf()?><input type="hidden" name="action" value="decision"><input type="hidden" name="resource_id" value="<?=e($conflict['id'])?>"><label>Decizie<select name="state" class="form-select"><option value="rejected">Păstrează informațiile proprii</option><option value="different_market">Fișa descrie altă piață sau formulă</option><option value="accepted">Preia într-o ciornă nouă</option></select></label><label>Motiv<textarea name="reason" class="form-control" maxlength="1500" required></textarea></label><label>Versiunea ciornei, dacă preiei datele<input name="version_key" class="form-control" maxlength="60"></label><button class="btn btn-primary">Înregistrează decizia</button></form><?php endif?></details><?php endforeach?></section></div>
